@@ -871,7 +872,9 @@ static void uasp_cmd_complete(struct usb_ep *ep, struct usb_request *req)
 		return;
 	}
 
-	usbg_submit_command(fu, req);
+	ret = usbg_submit_command(fu, req);
+	if (ret)
+		usb_ep_queue(fu->ep_cmd, req, GFP_ATOMIC);
 }
 
