 drivers/gpu/drm/bridge/Kconfig                   |   18 +
 drivers/gpu/drm/bridge/Makefile                  |    1 +
 drivers/gpu/drm/bridge/lontium-lt9611c.c         | 1283 ++++++++++++++++++++++
 4 files changed, 1312 insertions(+)

